    using System;
using System.Collections.Generic;

// Custom Min-Heap Priority Queue
class MinHeap {
    private List<(int val, int arrIdx, int elemIdx)> heap;

    public MinHeap()
    {
        heap = new List<(int, int, int)>();
    }

    private void Swap(int i, int j)
    {
        var temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }

    private void HeapifyUp(int index)
    {
        while (index > 0)
        {
            int parent = (index - 1) / 2;
            if (heap[index].val < heap[parent].val)
            {
                Swap(index, parent);
                index = parent;
            }
            else
                break;
        }
    }

    private void HeapifyDown(int index)
    {
        int last = heap.Count - 1;
        while (true)
        {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int smallest = index;

            if (left <= last && heap[left].val < heap[smallest].val)
                smallest = left;
            if (right <= last && heap[right].val < heap[smallest].val)
                smallest = right;

            if (smallest != index)
            {
                Swap(index, smallest);
                index = smallest;
            }
            else break;
        }
    }

    public void Add((int val, int arrIdx, int elemIdx) item)
    {
        heap.Add(item);
        HeapifyUp(heap.Count - 1);
    }

    public (int val, int arrIdx, int elemIdx) Pop() {
        var top = heap[0];
        heap[0] = heap[heap.Count - 1];
        heap.RemoveAt(heap.Count - 1);
        HeapifyDown(0);
        return top;
    }

    public int Count()
    {
        return heap.Count;
    }
}


